const scores = data?.coreValues || {};
const discipline = scores.discipline || 0;
const integrity = scores.integrity || 0;
const teamwork = scores.teamwork || 0;
const empathy = scores.empathy || 0;

const total = discipline + integrity + teamwork + empathy;
const average = total > 0 ? (total / 4).toFixed(2) : 0;

let grade = "D";
if (average >= 4.5) grade = "A";
else if (average >= 3.5) grade = "B";
else if (average >= 2.5) grade = "C";

let summary = "needs significant improvement in character building.";
if (grade === "A") summary = "has demonstrated outstanding character traits.";
else if (grade === "B") summary = "shows good character with minor areas for improvement.";
else if (grade === "C") summary = "displays average character, needing more focus and guidance.";

const sentence = `${data.studentName || "The student"} ${summary}`;

let actionPlan = "No specific action plan needed.";
if (grade === "C" || grade === "D") {
  actionPlan = "Requires weekly mentoring session and additional character building exercises.";
} else if (grade === "B") {
  actionPlan = "Continue current progress, focus on teamwork opportunities.";
} else {
  actionPlan = "Maintain excellent performance and mentor peers.";
}

return {
  evaluationResult: {
    suggestedActionPlan: actionPlan,
    averageScore: average,
    letterGrade: grade,
    summarySentence: sentence,
    rawTotal: total
  }
};
